		badRequest.getChildElement().element("unsubscribe").attribute("jid")
				.detach();
		badRequest.getChildElement().element("unsubscribe")
				.addAttribute("jid", "romeo@montague.lit");

		unsubscribe.process(element, jid, badRequest, null);

