                .query(query)
                .from(limitOffset.getOffsetStart() - 1)
                .size((limitOffset.hasLimit()) ? limitOffset.getLimit() : Integer.MAX_VALUE)
                .minScore(0.05f)
                .trackTotalHits(true)
                .fetchSource(new FetchSourceContext(fetchSource));

