			try (NBTOutputStream outStream = new NBTOutputStream(new DataOutputStream(out))) {
				outStream.writeTag(stack.getCompoundTag());
			} catch (Exception e) {
				e.printStackTrace();
			}
			total += out.toByteArray().length;
		} catch (Exception e) {
			e.printStackTrace();
		}
		return total;
	}

