                        String read = new String(journal.read(location, Journal.ReadType.ASYNC), "UTF-8");
                        if (read.equals("DATA" + index)) {
                            if (index % 4 == 0) {
                                journal.delete(location);
                            }
                            counter.incrementAndGet();
                        } else {
                            System.out.println(write);
                            System.out.println(read);
                        }
                    } catch (Exception ex) {
                        ex.printStackTrace();
                    }
